import sys

def read_input():
    import sys
    return sys.stdin.read().strip()

def process_input(input_data):
    lines = input_data.splitlines()
    n = int(lines[0])
    values = list(map(int, lines[1].split()))
    return n, values

def calculate_degree_and_next_value(n, values):
    differences = [values]
    degree = 0

    while True:
        new_diff = []
        for i in range(1, len(differences[-1])):
            new_diff.append(differences[-1][i] - differences[-1][i-1])
        differences.append(new_diff)
        degree += 1
        if all(x == new_diff[0] for x in new_diff):
            break

    # Calculate the next value
    next_value = values[-1]
    for i in range(degree):
        next_value += differences[i][-1]

    return degree, next_value

def main():
    input_data = read_input()
    n, values = process_input(input_data)
    degree, next_value = calculate_degree_and_next_value(n, values)
    print(degree, next_value)

if __name__ == "__main__":
    main()

import sys

def calculate_differences(sequence):
    differences = []
    for i in range(1, len(sequence)):
        differences.append(sequence[i] - sequence[i - 1])
    return differences

def find_degree_and_next_value(sequence):
    def find_degree(seq):
        if all(x == seq[0] for x in seq):
            return 0
        else:
            return 1 + find_degree(calculate_differences(seq))

    degree = find_degree(sequence)
    differences = sequence[:]
    for _ in range(degree):
        differences = calculate_differences(differences)

    next_value = sequence[-1] + differences[-1]
    return degree, next_value

def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    sequence = list(map(int, data[1:]))
    degree, next_value = find_degree_and_next_value(sequence)
    print(degree, next_value)

